207→  async runQuery(req: AgentQueryRequest, callbacks: ProviderRunCallbacks): Promise<ProviderRunResult> {
208→    const isResume = !!req.resumeSessionId
209→    const isNewSession = !isResume
210→    let sessionId = req.resumeSessionId || ''
211→    let sessionIdentified = false
212→
213→    // Eagerly start title generation for new sessions (runs in parallel with ACP setup)
214→    const eagerTitlePromise = isNewSession ? beginTitleGeneration(req.prompt) : null
215→
216→    // Mode instruction — only for ask mode. Plan mode is handled entirely by the
217→    // ACP mode config option, so no prompt instruction is needed.
218→    const modeInstruction = req.askMode
219→      ? 'You are in ask mode. Answer the question without making edits or executing side effects. Only read, search, and explain.'
220→      : ''
221→
222→    // Preprocess prompt (resolve @docs: and @file references)
223→    const { prompt: cleanedPrompt, contextChunks, contextString } = await preprocessPromptFull(
224→      this.ctx, req.prompt, req.cwd, { includeCodebaseContext: !isResume }
225→    )
226→
227→    // Build ACP content blocks
228→    const contentBlocks = await this.buildContentBlocks(cleanedPrompt, modeInstruction, contextString, req)
229→
230→    try {
231→      // Lazy-start ACP connection
232→      await this.connect().catch(err => {
233→        throw new Error(`${this.tag} ACP failed to start: ${extractErrorMessage(err)}`)
234→      })
235→      const authWarning = this._authFailed ? ` (authentication failed — check ${this.tag} login)` : ''
236→
237→      if (isResume) {
238→        await this.acpLoadSession(sessionId, req.cwd || process.cwd())
239→      } else {
240→        const result = await this.acpNewSession(req.cwd || process.cwd()).catch(err => {
241→          throw new Error(`Failed to create ${this.tag} session${authWarning}: ${extractErrorMessage(err)}`)
242→        })
243→        sessionId = result.sessionId
244→
245→        // Apply config options independently — each in its own try/catch so one
246→        // failure doesn't prevent the others from being set.
247→        if (result.configOptions) {
248→          if (req.model) {
249→            try { await this.applyModelConfig(sessionId, req.model, result.configOptions) }
250→            catch (e) { console.warn(`[${this.tag}] Model config failed:`, extractErrorMessage(e)) }
251→          }
252→          if (req.thinkingBudget) {
253→            try { await this.applyThinkingConfig(sessionId, req.thinkingBudget, result.configOptions) }
254→            catch (e) { console.warn(`[${this.tag}] Thinking config failed:`, extractErrorMessage(e)) }
255→          }
256→        }
257→        // Mode uses BOTH configOptions and legacy modes — run regardless
258→        try { await this.applyModeConfig(sessionId, req, result) }
259→        catch (e) { console.warn(`[${this.tag}] Mode config failed:`, extractErrorMessage(e)) }
260→      }
261→
262→      // Create stream adapter and register session update handler
263→      const adapter = new AcpStreamAdapter(this.id, sessionId, callbacks)
264→      const unsubSessionUpdate = this.onSessionUpdate((sid, update) => {
265→        if (sid === sessionId) {
266→          adapter.handleUpdate(update)
267→          // Store the raw ACP event
268→          this.ctx.sessionStore.appendRawMessage(sessionId, this.id, update)
269→        }
270→      })
271→
272→      const active: ActiveSession = { adapter, unsubSessionUpdate }
273→      this.activeSessions.set(sessionId, active)
274→
275→      // Set permission handler for this query — routes through shared permission system.
276→      // Detects ACP-standard switch_mode (plan exit) and shows plan review dialog.
277→      this.activePermissionHandler = async (params: RequestPermissionRequest) => {
278→        if (params.sessionId && params.sessionId !== sessionId) {
279→          // Not for this session — auto-allow
280→          const allowOption = params.options.find(o => o.kind === 'allow_once')
281→          return { outcome: { outcome: 'selected' as const, optionId: allowOption?.optionId || 'allow-once' } }
282→        }
283→
284→        const toolCall = params.toolCall
285→
286→        // ACP-standard plan exit: agent sends switch_mode permission when ready to leave architect mode
287→        if (toolCall.kind === 'switch_mode') {
288→          return this.handlePlanExitPermission(sessionId, adapter, params)
289→        }
290→
291→        const { id: permId, promise } = registerPendingPermission(sessionId)
292→        this.ctx.broadcaster.send('agent:permission-request', {
293→          id: permId,
294→          tool: toolCall.title || toolCall.kind || 'unknown',
295→          input: (toolCall.rawInput as Record<string, unknown>) || {},
296→        }, sessionId)
297→
298→        const { allowed } = await promise
299→        const findOption = (kind: string) => params.options.find(o => o.kind === kind)
300→        const optionId = allowed
301→          ? (findOption('allow_once') || findOption('allow_always'))?.optionId || 'allow-once'
302→          : (findOption('reject_once'))?.optionId || 'reject-once'
303→        return { outcome: { outcome: 'selected' as const, optionId } }
304→      }
305→
306→      // Set extension method handler — dispatches through config registry.
307→      this.activeExtMethodHandler = async (method: string, params: Record<string, unknown>) => {
308→        const handler = this.config.extensionHandlers?.[method]
309→        if (handler) {
310→          const extContext: AcpExtensionContext = {
311→            broadcaster: this.ctx.broadcaster,
312→            registerPendingPermission,
313→            registerPendingQuestion,
314→            adapter,
315→            callbacks,
316→          }
317→          return handler(sessionId, params, extContext)
318→        }
319→        return {}
320→      }
321→
322→      // Notify session identified
323→      callbacks.onSessionIdentified(sessionId)
324→      sessionIdentified = true
325→
326→      // Attach eager title generation now that we have the session ID
327→      if (eagerTitlePromise) {
328→        completeTitleGeneration(sessionId, eagerTitlePromise)
329→      }
330→
331→      // Emit injected context (triggers draft->session adoption in the renderer)
332→      const injectedContext = {
333→        mode: (req.askMode ? 'ask' : req.planMode ? 'plan' : 'code') as 'ask' | 'plan' | 'code',
334→        ...(contextString ? { systemPrompt: contextString } : {}),
335→        context: buildContextSummary(contextChunks),
336→      }
337→      callbacks.onMessage({ type: 'injected_context', session_id: sessionId, injectedContext }, sessionId)
338→
339→      // Persist injected_context and user prompt for reload (agent.ts skips
340→      // storage for handlesOwnStorage providers, so we write directly)
341→      this.ctx.sessionStore.appendRawMessage(sessionId, this.id, {
342→        type: 'injected_context',
343→        session_id: sessionId,
344→        injectedContext,
345→      })
346→      this.ctx.sessionStore.appendRawMessage(sessionId, this.id, {
347→        type: 'user',
348→        session_id: sessionId,
349→        message: { content: [{ type: 'text', text: cleanedPrompt }] },
350→      })
351→
352→      // Send prompt and wait for turn completion
353→      try {
354→        await this.acpPrompt(sessionId, contentBlocks)
355→      } catch (err) {
356→        const message = extractErrorMessage(err)
357→        callbacks.onError(`${this.tag} prompt failed${authWarning}: ${message}`, sessionId)
358→      }
359→
360→      // Finalize turn — emit accumulated assistant message
361→      adapter.finalizeTurn()
362→
363→      // Cleanup
364→      unsubSessionUpdate()
365→      this.activePermissionHandler = null
366→      this.activeExtMethodHandler = null
367→      this.activeSessions.delete(sessionId)
368→
369→    } catch (err) {
370→      const message = extractErrorMessage(err)
371→      if (!sessionIdentified) {
372→        if (!sessionId) {
373→          sessionId = `${this.tag}-failed-${Date.now()}-${Math.random().toString(36).slice(2)}`
374→        }
375→        callbacks.onSessionIdentified(sessionId)
376→        // Emit injected_context to trigger draft->session adoption in renderer
377→        // (user message is handled by agent.ts onSessionIdentified)
378→        callbacks.onMessage({
379→          type: 'injected_context',
380→          session_id: sessionId,
381→          injectedContext: { mode: (req.askMode ? 'ask' : req.planMode ? 'plan' : 'code') as 'ask' | 'plan' | 'code' },
382→        }, sessionId)
383→      }
384→      callbacks.onError(message, sessionId)
385→    } finally {
386→      callbacks.onDone(sessionId)
387→    }
388→
389→    return { queryKey: sessionId }
390→  }
